    methodologyTitle: "為何 ASTM E2149 是 FUZE 的主要效能測試",
    methodologyPara1: "品牌永續團隊常問:為何 FUZE 在 F3 與 F4 等級的主要效能測試是 ASTM E2149 而非 AATCC 100。簡答:ASTM E2149 是為非離子釋出、接觸殺菌型化學品設計的動態接觸測試。它鼓勵細菌細胞與元材料結合的纖維表面直接物理接觸 — 這正是 FUZE 的機制。",
    methodologyPara2Lead: "AATCC 100 將布料層層堆疊於接菌的試片周圍,測量存活的菌落形成單位。這是為 ",
    methodologyPara2Em: "離子釋出型",
    methodologyPara2Suffix: " 抗菌劑設計 — 這些化學品會將離子釋放至周圍水分中,並透過離子場殺菌。堆疊式的幾何結構對離子釋出型化學品有利;釋出的離子會飽和於層間空間。",
    methodologyPara3: "FUZE 於較高等級(F1 與 F2)能通過 AATCC 100,此時元材料密度足以克服測試幾何結構。在 F3 與 F4 等級,適合的主要效能測試為 ASTM E2149。品牌稽核時會收到四個等級的 ASTM E2149 結果,並於 F1、F2 加上 AATCC 100 作為互補檢視。",
